              targetId: explicitTargetId,
              portalId: explicitTargetId,
            });
          } else {
            const direction = explicitDirection === "up" ? "up" : "down";
            world?.emit?.("stair:traverse", {
              actor: actorId,
              targetId: explicitTargetId,
              direction,
            });
          }
          break;
        }

