import { defineComponent } from "../../lib/ecs-js/index.js";

// Vitality — basic hit points container for living things.
// Shape: { maxHp: number, hp: number }
export const Vitality = defineComponent('Vitality', {
  maxHp: 1,
  hp: 1
}, {
  validate(rec) {
    if (!rec) throw new Error('Vitality record required');
    if (typeof rec.maxHp !== 'number' || rec.maxHp <= 0) throw new Error('Vitality.maxHp must be > 0');
    if (typeof rec.hp !== 'number' || rec.hp < 0) throw new Error('Vitality.hp must be ≥ 0');
    if (rec.hp > rec.maxHp) rec.hp = rec.maxHp;
    return true;
  }
});
import { defineComponent } from "../../lib/ecs-js/index.js";

export const BaseStats = defineComponent("BaseStats", {
  strength: 0,
  intelligence: 0,
  dexterity: 0,
  vitality: 0,
  staminaRegen: 0,
  critChance: 0,
  critMultiplier: 1.5,
  baseDamageMin: 0,
  baseDamageMax: 0,
  perception: 5,
});
import { defineComponent } from "../../lib/ecs-js/index.js";
/**
 * Position component representing 2D (integer) coordinates.
 */
export const Position = defineComponent(
  "Position",
  { x: 0, y: 0 },
  {
    validate(rec) {
      if (!Number.isInteger(rec.x) || !Number.isInteger(rec.y)) {
        throw new Error(
          `Position: coordinates must be integers (x=${rec.x}, y=${rec.y})`
        );
      }
      return true;
    }
  }
);

