285	export function buildAgentObservation(world, opts = {}) {
286	  const view = buildWorldView(world);
287	  const playerRef = playerEntity(world);
288	  const playerId = int(playerRef?.id);
289	  const player = playerId > 0 ? playerObservation(world, playerId) : null;
290	  const radius = Math.max(1, int(opts.mapRadius, Math.max(8, int(view.playerVisionRadius, 8) + 2)));
291	  const origin = player?.pos || { x: 0, y: 0 };
292	  const x0 = origin.x - radius;
293	  const y0 = origin.y - radius;
294	  const width = radius * 2 + 1;
295	  const tiles = [];
296	  const visible = [];
297	  const explored = [];
298	  for (let y = y0; y <= origin.y + radius; y++) {
299	    const tileRow = [];
300	    const visibleRow = [];
301	    const exploredRow = [];
302	    for (let x = x0; x <= origin.x + radius; x++) {
303	      const isVisible = view.isVisible ? view.isVisible(x, y) === true : false;
304	      const isExplored = view.isExplored ? view.isExplored(x, y) === true : false;
305	      tileRow.push(isVisible || isExplored ? view.tileGrid?.getTile(x, y) ?? null : null);
306	      visibleRow.push(isVisible);
307	      exploredRow.push(isExplored);
308	    }
309	    tiles.push(tileRow);
310	    visible.push(visibleRow);
311	    explored.push(exploredRow);
312	  }
313	
314	  const entityList = (view.entities || []).map((rec) => entityObservation(world, rec));
315	  const observation = {
316	    protocol: "jshack-agent-v1",
317	    turn: int(world.step),
318	    seed: world.seed >>> 0,
319	    depth: int(view.currentDepth),
320	    player,
321	    map: { x0, y0, width, height: width, tiles, visible, explored, tileLegend: AGENT_TILE_LEGEND },
322	    entities: entityList,
323	    suggestedActions: player ? suggestions(world, view, player) : [],
324	  };
325	  if (opts.includeActionCatalog !== false) observation.actionCatalog = AGENT_ACTION_CATALOG;
326	  return observation;
327	}
